#include <stdio.h>
#include <limits.h>

#define N 5
#define INF INT_MAX

void dijkstra(int graph[N][N], int start) {
    int dist[N], visited[N] = {0};
    for (int i = 0; i < N; i++) dist[i] = INF;
    dist[start] = 0;
    for (int count = 0; count < N - 1; count++) {
        int min = INF, u = -1;
        for (int v = 0; v < N; v++)
            if (!visited[v] && dist[v] <= min) { min = dist[v]; u = v; }
        visited[u] = 1;
        for (int v = 0; v < N; v++)
            if (!visited[v] && graph[u][v] && dist[u] != INF && dist[u] + graph[u][v] < dist[v])
                dist[v] = dist[u] + graph[u][v];
    }
    for (int i = 0; i < N; i++)
        printf("Dist to %d: %d\n", i, dist[i]);
}

int main() {
    int graph[N][N] = {
        {0, 2, 0, 6, 0},
        {2, 0, 3, 8, 5},
        {0, 3, 0, 0, 7},
        {6, 8, 0, 0, 9},
        {0, 5, 7, 9, 0}
    };
    dijkstra(graph, 0);
    return 0;
}
